import axios from "axios";

const BASE_URL = "http://localhost:8080/api/github";

// ✅ TOKEN helper
const getAuthHeader = () => ({
  headers: {
    Authorization: `Bearer ${localStorage.getItem("token")}`,
  },
});

// ✅ 1. Get Logged-in Username (Owner)
export const fetchLoggedUser = async () => {
  return await axios.get(`${BASE_URL}/me`, getAuthHeader());
};

// ✅ 2. Get Repository List
export const fetchUserRepos = async () => {
  return await axios.get(`${BASE_URL}/repos`, getAuthHeader());
};

// ✅ 3. Fetch PR Analytics
export const fetchPRData = async (payload) => {
  return await axios.post(`${BASE_URL}/prs`, payload, getAuthHeader());
};
